import sys,json,re,html
from pathlib import Path
sys.path.insert(0,'/tmp/integral-tools')
from latex2mathml.converter import convert
R=Path(__file__).parent
def m(tex,block=False):
    result=convert(tex,display='block' if block else 'inline')
    return '<span class="int-formula">'+result+'</span>' if block else result
def H(text):
    text=re.sub(r'\[\[(.*?)\]\]',lambda z:m(z[1],True),text,flags=re.S)
    def inline(z):
        tex=z[1];tex+='}'*max(0,tex.count('{')-tex.count('}'))
        return m(tex)
    return re.sub(r'\{\{(.*?)\}\}\}*',inline,text,flags=re.S)
def K(term,label):return '<button type="button" class="rm-keyword" data-term="int-'+term+'">'+label+'</button>'
def S(title,text):return dict(title=title,html=H(text))
def C(title,*steps):return dict(title=title,stepMode='replace',steps=list(steps))
def Q(question,options,answer,feedback,hints=None):
    assert len(options)==4 and len(set(options))==4
    return dict(question=question,options=options,answer=answer,feedback=feedback,feedbackByOption=hints or [feedback if i==answer else 'Controlla questo passaggio: '+feedback for i in range(4)])
def Sec(id,title,cards,questions):return dict(id=id,title=title,cards=cards,quiz=dict(questions=questions))
def Recap(lines):return dict(id='recap',title='La lezione in pillole',cards=[C('La lezione in pillole',S('', '<ul>'+''.join('<li>'+x+'</li>' for x in lines)+'</ul>'))])
lessons={}
def L(id,title,sections):
    lessons[id]=dict(title=title,subtitle='Matematica · Quinta liceo scientifico e primo anno universitario · Bozza in lavorazione',version=1,status='work-in-progress',sections=sections)

L('integrali-immediati','Primitive e integrali immediati',[
 Sec('primitive','Risalire dalla derivata alla funzione',[
  C('Che cosa stiamo cercando?',S('Il problema inverso',r'Sai derivare {{x^3}} e ottenere {{3x^2}}. Ora invertiamo la domanda: <strong>quale funzione ha derivata {{3x^2}}?</strong> Una risposta è {{x^3}}. Questa funzione è una '+K('primitiva','primitiva')+'.<br><br>Per seguire il percorso servono le derivate fondamentali, la derivata della funzione composta e le operazioni con polinomi e frazioni.'),S('La definizione',r'Su un intervallo {{I}}, una funzione {{F}} è una <strong>primitiva di {{f}}</strong> se è derivabile e vale [[F\prime(x)=f(x)]] per ogni {{x}} dell’intervallo. <strong>La verifica si fa derivando il risultato.</strong>')),
  C('Perché compare una costante?',S('Non c’è una sola risposta',r'Anche {{x^3+5}} e {{x^3-2}} hanno derivata {{3x^2}}. La derivata di una costante è zero: non possiamo ricostruirla dalla sola derivata.<br><br>Su uno stesso intervallo, tutte le primitive differiscono per una costante. Scriviamo [[\int 3x^2\,dx=x^3+C]] con {{C\in\mathbb{R}}.'),S('Leggere i simboli',K('indefinito','L’integrale indefinito')+r' indica la famiglia di tutte le primitive. {{3x^2}} è la <strong>funzione integranda</strong>; {{dx}} indica che integriamo rispetto a {{x}}.<br><br>Con due estremi, come in {{\int_0^1 3x^2\,dx}}, si parla invece di <strong>integrale definito</strong>: il risultato è un numero. Lo studieremo nell’ultima lezione.'),S('Un dato iniziale sceglie una primitiva',r'Se conosciamo anche {{F(0)=7}}, dalla famiglia {{F(x)=x^3+C}} otteniamo {{C=7}}.<br><br>In economia, conoscere un costo marginale permette di ricostruire il costo totale; per determinarlo completamente serve anche un dato come il costo fisso.'))
 ],[
 Q('Quale condizione definisce una primitiva F di f su un intervallo?',['F′(x) = f(x).','f′(x) = F(x).','F(x) = f(x).','F′(x) = 0 per ogni funzione f.'],0,'Devi derivare F e ritrovare f.'),
 Q('Perché nell’integrale indefinito aggiungiamo C?',['Per cambiare la variabile.','Perché la derivata di una costante è zero.','Per indicare un errore di misura.','Perché C è sempre uguale a 1.'],1,'La derivazione perde l’informazione sulla costante additiva.'),
 Q('Una primitiva di 2x è F(x) = x² + C. Se F(0) = 4, quanto vale C?',['0','2','4','Non si può determinare.'],2,'Sostituisci x = 0: F(0) = C = 4.')]),
 Sec('potenze','Potenze, radici e il caso 1/x',[
 C('La regola delle potenze',S('Aumenta l’esponente, poi dividi',r'Per una potenza di {{x}}, [[\int x^p\,dx=\frac{x^{p+1}}{p+1}+C\qquad(p\ne-1)]] La formula vale sugli intervalli in cui la potenza reale è definita e la primitiva è derivabile. Per esponenti reali qualsiasi possiamo lavorare su {{x>0}}.'),S('Il denominatore ha un motivo',r'Per esempio, [[\int x^4\,dx=\frac{x^5}{5}+C]] Derivando {{x^5/5}}, il fattore {{5}} si semplifica e rimane {{x^4}}. Senza la divisione per {{5}} otterremmo cinque volte la funzione richiesta.')),
 C('Riscrivere prima di integrare',S('Le radici sono potenze',r'[[\sqrt{x}=x^{1/2}\qquad\frac{1}{x^2}=x^{-2}]] Perciò [[\int\sqrt{x}\,dx=\frac{2}{3}x^{3/2}+C]] e [[\int\frac{1}{x^2}\,dx=-\frac{1}{x}+C]] Nel secondo esempio lavoriamo su un intervallo che non contiene {{0}}.'),S('L’eccezione che porta al logaritmo',r'Per {{p=-1}} la formula precedente dividerebbe per zero. Si usa un’altra derivata fondamentale: [[\int\frac{1}{x}\,dx=\ln|x|+C]] Vale su un intervallo contenuto in {{x>0}} oppure in {{x<0}}. Il '+K('modulo','valore assoluto')+r' rende il logaritmo definito anche quando {{x}} è negativo. Le costanti possono essere diverse sui due intervalli.'))
 ],[
 Q('Qual è ∫ x³ dx?',['3x² + C','x⁴ + C','x⁴/4 + C','x³/3 + C'],2,'Aumenta l’esponente da 3 a 4 e dividi per 4.'),
 Q('Qual è ∫ 1/x² dx, su un intervallo che non contiene zero?',['ln|x| + C','−1/x + C','1/x + C','−2/x³ + C'],1,'Riscrivi 1/x² = x⁻²: la nuova potenza è x⁻¹ e devi dividere per −1.'),
 Q('Per quale esponente la regola x^(p+1)/(p+1) non si applica?',['0','1','−1','1/2'],2,'Per p = −1 il denominatore p+1 è zero: serve ln|x|.')]),
 Sec('formule','Le formule da riconoscere',[
 C('Esponenziali e funzioni goniometriche',S('Le primitive fondamentali',r'[[\int e^x\,dx=e^x+C\qquad\int a^x\,dx=\frac{a^x}{\ln a}+C]] Nella seconda formula {{a>0}} e {{a\ne1}}.<br><br>[[\int\sin x\,dx=-\cos x+C\qquad\int\cos x\,dx=\sin x+C]] Gli argomenti goniometrici sono in <strong>radianti</strong>. Il segno meno nella primitiva del seno viene dalla derivata del coseno.'),S('Altre quattro forme utili',r'[[\int\frac{1}{\cos^2 x}\,dx=\tan x+C]] [[\int\frac{1}{\sin^2 x}\,dx=-\cot x+C]] [[\int\frac{1}{1+x^2}\,dx=\arctan x+C]] [[\int\frac{1}{\sqrt{1-x^2}}\,dx=\arcsin x+C]] Rispetta i domini: i denominatori non devono annullarsi; nell’ultima formula {{-1<x<1}}.')),
 C('Somme e costanti',S('La linearità',K('linearita','La linearità')+r' permette di integrare una somma termine per termine e di portare fuori i fattori costanti. [[\int(3x^2-2x+4)\,dx=x^3-x^2+4x+C]] <strong>Una costante integrata diventa costante per {{x}}</strong>: {{\int4\,dx=4x+C}}.'),S('Non vale per prodotti e quozienti',r'In generale non puoi integrare separatamente i fattori di un prodotto o il numeratore e il denominatore di una frazione.<br><br>Per esempio, {{\int x\cdot x\,dx=\int x^2\,dx=x^3/3+C}}. Moltiplicare due primitive darebbe un risultato diverso. Nelle prossime lezioni studieremo come trattare questi casi.'))
 ],[
 Q('Qual è ∫ sin x dx?',['cos x + C','−cos x + C','−sin x + C','sin x + C'],1,'La derivata di −cos x è sin x.'),
 Q('Qual è ∫ (2x + 3) dx?',['x² + 3x + C','2x² + 3 + C','x² + 3 + C','2 + C'],0,'Integra i due termini: 2x diventa x², mentre 3 diventa 3x.'),
 Q('Quale trasformazione è sempre valida quando esistono le primitive?',['Integrare un prodotto moltiplicando le primitive.','Integrare una frazione dividendo le primitive.','Portare fuori dall’integrale un fattore costante.','Portare fuori dall’integrale qualsiasi fattore che dipende da x.'],2,'La linearità riguarda somme e fattori costanti, non prodotti o quozienti arbitrari.')]),
 Recap(['<strong>Primitiva:</strong> derivandola ritrovi la funzione integranda.',r'<strong>Integrale indefinito:</strong> una famiglia di funzioni, con {{+C}}.',r'<strong>Potenze:</strong> aumenta l’esponente e dividi; per {{1/x}} usa {{\ln|x|}}.','<strong>Prima riscrivi, poi integra:</strong> radici e frazioni possono diventare potenze.','<strong>Controlla il risultato derivando</strong>, e conserva le condizioni sul dominio.'])])

L('integrali-sostituzione','Funzioni composte e integrazione per sostituzione',[
 Sec('riconoscere','La derivata della funzione interna',[
 C('Una struttura da riconoscere',S('La regola della catena, al contrario',r'Quando derivi {{G(g(x))}}, ottieni {{G\prime(g(x))g\prime(x)}}. Integrando cerchiamo proprio questa struttura: <strong>una funzione composta moltiplicata per la derivata della funzione interna</strong>.<br><br>Per esempio, [[\int 2x(x^2+3)^4\,dx]] La funzione interna è {{g(x)=x^2+3}}; la sua derivata è il fattore {{2x}} già presente.'),S('Integra la funzione esterna',r'La primitiva di {{u^4}} è {{u^5/5}}. Rimettendo {{u=x^2+3}} otteniamo [[\int2x(x^2+3)^4\,dx=\frac{(x^2+3)^5}{5}+C]] Non occorre sviluppare la quarta potenza. Derivando il risultato ricompare anche il fattore {{2x}}.')),
 C('Un fattore manca?',S('Compensare una costante',r'In [[\int x(x^2+3)^4\,dx]] la derivata interna è {{2x}}, ma abbiamo {{x}}. Poiché {{x=(1/2)2x}}, [[\int x(x^2+3)^4\,dx=\frac12\int2x(x^2+3)^4\,dx]] e quindi il risultato è {{(x^2+3)^5/10+C}}.'),S('Una costante non è una funzione',r'Puoi compensare un fattore <strong>costante</strong>. Non puoi inserire un fattore che dipende da {{x}} e dimenticarne il reciproco.<br><br>In {{\int(x^2+3)^4\,dx}} manca tutto il fattore {{2x}}: la formula precedente non si applica direttamente. Qui puoi sviluppare la potenza e integrare il polinomio.'))
 ],[
 Q('In ∫ 2x(x²+3)⁴ dx, qual è una funzione interna utile?',['2x','(x²+3)⁴','x²+3','x⁵'],2,'La derivata di x²+3 è 2x: il fattore che accompagna la potenza.'),
 Q('In ∫ x(x²+3)⁴ dx, quale fattore costante compensa la derivata interna 2x?',['2','1/2','x','1/x'],1,'x è metà di 2x, quindi fuori dall’integrale compare 1/2.'),
 Q('La formula per la potenza composta si applica direttamente a ∫ (x²+3)⁴ dx?',['Sì, basta aumentare l’esponente.','Sì, basta dividere per 2.','No: manca il fattore 2x, non una semplice costante.','No: nessun polinomio ha una primitiva.'],2,'Controlla sempre la derivata interna: qui non è presente.')]),
 Sec('schemi','Potenze, esponenziali e logaritmi composti',[
 C('Lo stesso riconoscimento, altre formule',S('Tre schemi frequenti',r'[[\int g\prime(x)[g(x)]^p\,dx=\frac{[g(x)]^{p+1}}{p+1}+C\quad(p\ne-1)]] [[\int g\prime(x)e^{g(x)}\,dx=e^{g(x)}+C]] [[\int\frac{g\prime(x)}{g(x)}\,dx=\ln|g(x)|+C]] Nell’ultimo schema {{g(x)\ne0}}. Per le potenze valgono le condizioni sul dominio già viste.'),S('Due esempi, due controlli',r'[[\int3e^{3x-2}\,dx=e^{3x-2}+C]] perché la derivata di {{3x-2}} è {{3}}.<br><br>[[\int\frac{2x}{x^2+4}\,dx=\ln(x^2+4)+C]] perché il numeratore è la derivata del denominatore. Qui {{x^2+4>0}}, quindi il modulo non è necessario.')),
 C('L’argomento lineare',S('Il fattore 1/a',r'Se l’argomento è {{ax+b}}, la sua derivata è la costante {{a}}. Per {{a\ne0}}, [[\int e^{ax+b}\,dx=\frac1a e^{ax+b}+C]] Per esempio {{\int e^{5x+1}\,dx=e^{5x+1}/5+C}}. Lo stesso controllo vale per seno, coseno e potenze di {{ax+b}}.'),S('Anche arctan e arcsin',r'[[\int\frac{3}{1+9x^2}\,dx=\arctan(3x)+C]] [[\int\frac{2}{\sqrt{1-4x^2}}\,dx=\arcsin(2x)+C]] Nella prima riconosci {{1+(3x)^2}}; nella seconda {{1-(2x)^2}}. La seconda formula vale per {{|x|<1/2}}.'))
 ],[
 Q('Qual è ∫ e^(4x) dx?',['e^(4x) + C','4e^(4x) + C','e^(4x)/4 + C','e^x/4 + C'],2,'Derivando l’esponenziale compare un fattore 4: lo compensi con 1/4.'),
 Q('Qual è ∫ 2x/(x²+4) dx?',['ln(x²+4) + C','1/(x²+4) + C','arctan x + C','2ln(x²+4) + C'],0,'2x è esattamente la derivata del denominatore.'),
 Q('Per ∫ 1/(1+9x²) dx, quale fattore deve accompagnare arctan(3x)?',['3','1/9','1','1/3'],3,'La derivata di arctan(3x) è 3/(1+9x²).')]),
 Sec('cambio','Scrivere il cambio di variabile',[
 C('Una sostituzione completa',S('Scegli la nuova variabile',K('sostituzione','La sostituzione')+r' rende esplicito il riconoscimento. Consideriamo [[\int\frac{x}{x^2+5}\,dx]] Poniamo {{u=x^2+5}}. Derivando otteniamo {{du=2x\,dx}}, cioè {{x\,dx=du/2}}.'),S('Cambia anche il differenziale',r'[[\int\frac{x}{x^2+5}\,dx=\frac12\int\frac1u\,du=\frac12\ln|u|+C]] L’integrale trasformato deve essere scritto <strong>tutto nella nuova variabile</strong>: non lasciare {{x}} insieme a {{du}}.'),S('Ritorna alla variabile iniziale',r'Sostituendo di nuovo {{u=x^2+5}} troviamo [[\frac12\ln(x^2+5)+C]] Il differenziale è una notazione che tiene traccia della derivata interna; non basta cambiare il nome della variabile.')),
 C('Quando è più utile cambiare variabile',S('Una radice', r'[[\int\frac{1}{1+\sqrt{x}}\,dx]] Su {{x>0}} scegliamo {{u=\sqrt{x}}}, cioè {{x=u^2}} e {{dx=2u\,du}}. La radice scompare: [[\int\frac{2u}{1+u}\,du=\int\left(2-\frac{2}{1+u}\right)du]]'),S('Integra e torna a x',r'[[2u-2\ln|1+u|+C]] diventa [[2\sqrt{x}-2\ln(1+\sqrt{x})+C]] Qui {{1+\sqrt{x}>0}}. A differenza degli esempi precedenti, il cambio di variabile ha anche semplificato la forma della funzione.'))
 ],[
 Q('Se u = x²+5, quale relazione è corretta?',['du = dx','du = 2x dx','du = x dx','dx = 2x du'],1,'Deriva u rispetto a x: u′ = 2x.'),
 Q('Dopo una sostituzione, come deve essere scritto l’integrale trasformato?',['Con u nell’integranda e dx alla fine.','Con x e u mescolati senza relazione.','Interamente nella nuova variabile, compreso il differenziale.','Senza differenziale.'],2,'Trasforma sia la funzione sia il differenziale.'),
 Q('Se u = √x e x = u², che cosa sostituisce dx?',['du/(2u)','2u du','u² du','2 du'],1,'Derivando x = u² ottieni dx = 2u du.')]),
 Recap(['<strong>Cerca funzione interna e sua derivata.</strong>','<strong>Compensa solo le costanti</strong> senza cambiare la funzione integranda.','<strong>Scrivi la sostituzione e il differenziale</strong>, poi trasforma tutto l’integrale.',r'<strong>Ritorna a {{x}}</strong> negli integrali indefiniti.','<strong>Deriva il risultato:</strong> il controllo rivela subito un fattore dimenticato.'])])

L('integrali-razionali-lineari','Funzioni razionali fratte: divisione e fratti semplici',[
 Sec('preparare','Prima di scomporre',[
 C('Un rapporto di polinomi',S('La funzione e il suo dominio','Una '+K('razionale','funzione razionale fratta')+r' è un rapporto {{N(x)/D(x)}} tra polinomi, con {{D(x)\ne0}}. La prima domanda non è «quale formula uso?», ma <strong>«posso semplificare la frazione?»</strong>.<br><br>Per esempio, {{(x^2-1)/(x-1)=x+1}} per {{x\ne1}}. Possiamo integrare {{x+1}}, ma la semplificazione non restituisce il punto escluso dal dominio.'),S('Confronta i gradi',r'Se il grado del numeratore è almeno quello del denominatore, possiamo fare la <strong>divisione tra polinomi</strong>: [[N(x)=Q(x)D(x)+R(x)]] e quindi [[\frac{N(x)}{D(x)}=Q(x)+\frac{R(x)}{D(x)}]] Il resto ha grado minore del denominatore, oppure è zero.')),
 C('Una divisione che semplifica il calcolo',S('Ricostruisci il numeratore',r'Consideriamo [[\int\frac{x^2+2x+3}{x+1}\,dx]] Poiché [[x^2+2x+3=(x+1)(x+1)+2]] il quoziente è {{x+1}} e il resto è {{2}}. Puoi verificare l’identità moltiplicando.'),S('Due integrali immediati',r'[[\int\left(x+1+\frac{2}{x+1}\right)dx]] ha come risultato [[\frac{x^2}{2}+x+2\ln|x+1|+C]] Lavoriamo su un intervallo che non contiene {{-1}}. La divisione ha isolato una parte polinomiale e una frazione più semplice.'))
 ],[
 Q('Quando è utile dividere il numeratore per il denominatore prima dei fratti semplici?',['Quando il grado del numeratore è almeno quello del denominatore.','Solo se il denominatore è una costante.','Quando il numeratore ha sempre grado minore.','Solo quando non ci sono termini in x.'],0,'La divisione separa una parte polinomiale e una frazione con numeratore di grado minore.'),
 Q('Qual è la riscrittura di (x²+2x+3)/(x+1)?',['x+1','x+1+2/(x+1)','x+2+3/(x+1)','x+1+2x/(x+1)'],1,'Moltiplica x+1 per il denominatore e aggiungi il resto 2.'),
 Q('Semplificando (x²−1)/(x−1) in x+1, che cosa accade a x=1?',['Diventa ammesso nel dominio originale.','La primitiva è sempre zero.','Resta escluso dal dominio originale.','Non esistono primitive su nessun intervallo.'],2,'L’espressione originale non è definita in x=1: la semplificazione non cambia quel fatto.')]),
 Sec('distinti','Fattori lineari distinti',[
 C('Scomporre in fratti semplici',S('La forma da cercare','Se il denominatore è il prodotto di fattori lineari distinti, cerchiamo una somma di '+K('fratti','fratti semplici')+r'. Per esempio, [[\frac{3x+1}{(x-1)(x+1)}=\frac{A}{x-1}+\frac{B}{x+1}]] {{A}} e {{B}} sono costanti da determinare. La somma deve coincidere con la frazione iniziale.'),S('Determina i coefficienti',r'Portando al denominatore comune otteniamo l’identità [[3x+1=A(x+1)+B(x-1)]] Con {{x=1}} troviamo {{4=2A}}, quindi {{A=2}}. Con {{x=-1}} troviamo {{-2=-2B}}, quindi {{B=1}}.<br><br>Questi valori si sostituiscono <strong>nell’identità polinomiale ottenuta dopo aver eliminato i denominatori</strong>, non nella frazione originale.'),S('Ora puoi integrare',r'[[\int\frac{3x+1}{x^2-1}\,dx=2\ln|x-1|+\ln|x+1|+C]] Su ogni intervallo che non contiene {{-1}} o {{1}}, questa è una famiglia di primitive. Derivando ritrovi {{2/(x-1)+1/(x+1)}} e quindi la frazione iniziale.')),
 C('Un altro modo per trovare A e B',S('Confrontare i coefficienti',r'Sviluppando l’identità precedente: [[3x+1=(A+B)x+(A-B)]] I coefficienti delle stesse potenze devono coincidere: [[A+B=3\qquad A-B=1]] Il sistema dà di nuovo {{A=2}}, {{B=1}}. Questo metodo funziona anche quando sostituire valori particolari non determina subito tutte le costanti.'))
 ],[
 Q('Qual è la forma adatta per 1/[(x−2)(x+3)]?',['A/(x−2) + B/(x+3)','(Ax+B)/[(x−2)(x+3)] senza separare i termini','A/(x−2)² + B/(x+3)²','A(x−2) + B(x+3)'],0,'A ciascun fattore lineare distinto corrisponde una frazione con numeratore costante.'),
 Q('Se 3x+1 = A(x+1)+B(x−1) per ogni x, quali equazioni ottieni?',['A+B=1 e A−B=3','A+B=3 e A−B=1','A=B=3','A+B=3 e A+B=1'],1,'Raccogli il coefficiente di x e il termine costante.'),
 Q('La primitiva di 2/(x−1) è…',['2/(x−1)² + C','ln|x−1| + C','2ln|x−1| + C','−2ln|x−1| + C'],2,'La derivata di ln|x−1| è 1/(x−1): il fattore 2 rimane.')]),
 Sec('ripetuti','Fattori lineari ripetuti',[
 C('Una potenza richiede più termini',S('Non saltare le potenze inferiori',r'Se compare {{(x-a)^m}}, nello schema generale dei fratti semplici inseriamo <strong>tutte le potenze da {{1}} a {{m}}</strong>. Per esempio, [[\frac{x+2}{(x-1)^2}=\frac{A}{x-1}+\frac{B}{(x-1)^2}]] Moltiplicando per {{(x-1)^2}} troviamo {{x+2=A(x-1)+B}}; quindi {{A=1}} e {{B=3}}.'),S('Un logaritmo e una potenza',r'[[\int\frac{x+2}{(x-1)^2}\,dx=\ln|x-1|-\frac{3}{x-1}+C]] Il secondo termine deriva da {{3(x-1)^{-2}}: la sua primitiva è {{-3(x-1)^{-1}}}. <strong>Il quadrato al denominatore non produce un logaritmo</strong>.'),S('Un fattore ripetuto dentro un prodotto',r'Per il denominatore {{x(x-1)^2}}, lo schema generale è [[\frac{A}{x}+\frac{B}{x-1}+\frac{D}{(x-1)^2}]] Le costanti possono anche risultare zero: lo scopriremo dai calcoli. Non omettere un termine prima di averlo verificato.'))
 ],[
 Q('Qual è lo schema generale per una frazione propria con denominatore (x−1)³?',['A/(x−1)³ soltanto','A/(x−1) + B/(x−1)² + D/(x−1)³','A/(x−1) + B/(x−1)³ soltanto','Ax+B'],1,'Un fattore ripetuto richiede tutte le potenze fino alla sua molteplicità.'),
 Q('Qual è ∫ 3/(x−1)² dx?',['3ln|x−1| + C','3/(x−1) + C','−3/(x−1) + C','−6/(x−1)³ + C'],2,'Usa la potenza −2, aumentando l’esponente a −1 e dividendo per −1.'),
 Q('Nell’identità x+2 = A(x−1)+B, quanto valgono A e B?',['A=1, B=3','A=1, B=2','A=2, B=1','A=0, B=3'],0,'Il coefficiente di x dà A=1; il termine costante dà −1+B=2.')]),
 Recap(['<strong>Controlla il dominio</strong> e semplifica se puoi.','<strong>Confronta i gradi:</strong> la divisione può isolare una parte polinomiale.','<strong>Fattori distinti:</strong> un fratto per ogni fattore lineare.','<strong>Fattori ripetuti:</strong> inserisci tutte le potenze necessarie.','<strong>Trova le costanti con un’identità</strong>, integra la somma e verifica derivando.'])])

L('integrali-razionali-quadratiche','Funzioni razionali fratte: denominatori quadratici',[
 Sec('classificare','Che cosa dice il denominatore?',[
 C('Un trinomio, tre possibilità',S('Il discriminante', r'Per {{ax^2+bx+c}}, con {{a\ne0}}, calcola il '+K('discriminante','discriminante')+r' {{\Delta=b^2-4ac}}.<br><br><strong>{{\Delta>0}}:</strong> due radici reali distinte, quindi due fattori lineari.<br><strong>{{\Delta=0}}:</strong> una radice doppia, quindi un fattore lineare ripetuto.<br><strong>{{\Delta<0}}:</strong> nessuna radice reale; il trinomio non si scompone in fattori lineari reali.'),S('Prima guarda anche il numeratore',r'Non serve sempre una scomposizione: [[\int\frac{2x+2}{x^2+2x+5}\,dx=\ln(x^2+2x+5)+C]] Il numeratore è la derivata del denominatore. Il denominatore è sempre positivo: {{x^2+2x+5=(x+1)^2+4}}.')),
 C('Completare il quadrato',S('Far comparire una forma nota','Quando il trinomio non ha radici reali, il '+K('quadrato','completamento del quadrato')+r' permette spesso di riconoscere l’arcotangente. [[x^2+2x+5=(x+1)^2+4]] Perciò [[\int\frac{1}{x^2+2x+5}\,dx=\frac12\arctan\frac{x+1}{2}+C]] La sostituzione {{u=(x+1)/2}} dà {{dx=2du}} e denominatore {{4(1+u^2)}}.'))
 ],[
 Q('Che cosa significa Δ<0 per un trinomio quadratico reale?',['Ha due radici reali distinte.','Ha una radice doppia.','Non ha radici reali.','È sempre uguale a zero.'],2,'Non puoi scomporlo in due fattori lineari reali.'),
 Q('Qual è il completamento del quadrato per x²+2x+5?',['(x+1)²+4','(x+2)²+1','(x+1)²+5','(x−1)²+4'],0,'Sviluppa (x+1)²: ottieni x²+2x+1 e devi aggiungere 4.'),
 Q('Qual è ∫ 1/(x²+4) dx?',['arctan x + C','2arctan(x/2) + C','arctan(x/2)/2 + C','ln(x²+4) + C'],2,'Poni u=x/2: dx=2du e il denominatore diventa 4(1+u²).')]),
 Sec('numeratore','Una parte logaritmica e una parte arctan',[
 C('Costruire la derivata del denominatore',S('Dividere il numeratore in due pezzi',r'Consideriamo [[\int\frac{3x+4}{x^2+2x+5}\,dx]] La derivata del denominatore è {{2x+2}}. Scriviamo [[3x+4=\frac32(2x+2)+1]] Controlla: il primo pezzo è {{3x+3}}, quindi manca {{1}}.'),S('Integra i due pezzi',r'[[\frac32\int\frac{2x+2}{x^2+2x+5}\,dx+\int\frac{1}{x^2+2x+5}\,dx]] Il primo integrale è un logaritmo, il secondo è quello appena studiato. Il risultato è [[\frac32\ln(x^2+2x+5)+\frac12\arctan\frac{x+1}{2}+C]]'),S('La strategia generale',r'Per un numeratore lineare {{mx+n}} cerca costanti {{\lambda}} e {{\mu}} tali che [[mx+n=\lambda(2ax+b)+\mu]] La parte con la derivata del denominatore dà un logaritmo; quella costante si tratta completando il quadrato. È una <strong>riscrittura algebrica</strong>, non una nuova formula da memorizzare.'))
 ],[
 Q('Come riscrivi 3x+4 usando la derivata 2x+2?',['3(2x+2)+4','(3/2)(2x+2)+1','(3/2)(2x+2)+4','(1/2)(2x+2)+3'],1,'Moltiplicando per 3/2 ottieni 3x+3: devi aggiungere 1.'),
 Q('Il pezzo con il numeratore uguale alla derivata del denominatore produce…',['Un logaritmo del valore assoluto del denominatore.','Sempre una potenza cubica.','Sempre un’arcotangente.','Il rapporto fra le primitive.'],0,'È lo schema g′/g; il modulo si può togliere se g è positivo.'),
 Q('Nel risultato di ∫ (3x+4)/(x²+2x+5) dx, perché compare anche arctan?',['Perché qualsiasi frazione produce arctan.','Perché la costante d’integrazione dipende da x.','Perché resta un numeratore costante sopra un quadratico senza radici reali.','Perché il discriminante è positivo.'],2,'Dopo aver isolato la derivata del denominatore resta 1/[(x+1)²+4].')]),
 Sec('misti','Un denominatore con fattori diversi',[
 C('Lo schema con un fattore quadratico',S('Il numeratore deve essere lineare',r'Per un fattore quadratico irriducibile {{q(x)}}, il numeratore del fratto semplice ha la forma {{Bx+D}}, non soltanto una costante. Per esempio, [[\frac{1}{x(x^2+1)}=\frac{A}{x}+\frac{Bx+D}{x^2+1}]] Ogni numeratore ha grado minore del fattore che sta al denominatore.'),S('Trova le costanti',r'Moltiplicando per {{x(x^2+1)}} otteniamo [[1=A(x^2+1)+(Bx+D)x]] Confrontando i coefficienti: {{A=1}}, {{A+B=0}}, {{D=0}}. Quindi [[\frac{1}{x(x^2+1)}=\frac1x-\frac{x}{x^2+1}]]'),S('Integra e controlla',r'[[\int\frac{1}{x(x^2+1)}\,dx=\ln|x|-\frac12\ln(x^2+1)+C]] La formula vale separatamente su {{x>0}} e {{x<0}}. <strong>Non compare sempre arctan:</strong> qui il secondo numeratore è proporzionale alla derivata del denominatore.'),S('Se il quadratico è ripetuto',r'Per un fattore {{q(x)^2}}, lo schema generale contiene [[\frac{B_1x+D_1}{q(x)}+\frac{B_2x+D_2}{q(x)^2}]] I pezzi con {{q(x)^2}} possono richiedere ulteriori passaggi. Per il caso base, [[\int\frac{dx}{(1+x^2)^2}=\frac{x}{2(1+x^2)}+\frac12\arctan x+C]] Puoi controllare la formula derivando; i casi con potenze più alte saranno un approfondimento.'))
 ],[
 Q('Quale numeratore usi nello schema generale sopra un fattore quadratico irriducibile?',['Sempre 1.','Un polinomio lineare Bx+D.','Un polinomio dello stesso grado del denominatore.','Sempre x².'],1,'Nel fratto semplice il numeratore ha grado minore del fattore quadratico.'),
 Q('Qual è la scomposizione di 1/[x(x²+1)]?',['1/x + x/(x²+1)','1/x − x/(x²+1)','1/x − 1/(x²+1)','x/(x²+1)'],1,'Portando al denominatore comune il numeratore è (x²+1)−x²=1.'),
 Q('Per ∫ x/(x²+1) dx, qual è la primitiva?',['arctan x + C','ln(x²+1) + C','ln(x²+1)/2 + C','−1/(x²+1) + C'],2,'La derivata del denominatore è 2x: devi compensare con 1/2.')]),
 Recap([r'<strong>Il discriminante orienta la scelta</strong>, ma controlla prima se riconosci già {{g\prime/g}}.',r'<strong>Completa il quadrato</strong> per riconoscere {{1/(1+u^2)}}.','<strong>Dividi il numeratore:</strong> derivata del denominatore più una costante.','<strong>Un fattore quadratico richiede un numeratore lineare</strong> nello schema generale.','<strong>Logaritmo o arctan?</strong> Decide la forma del numeratore dopo la riscrittura.'])])

L('integrali-parti','Integrazione per parti',[
 Sec('regola','Usare la derivata di un prodotto',[
 C('Trasformare un integrale in uno più semplice',S('Da dove viene la regola',r'La derivata di un prodotto è [[(uv)\prime=u\prime v+uv\prime]] Riordinando e integrando ricaviamo [[\int u(x)v\prime(x)\,dx=u(x)v(x)-\int u\prime(x)v(x)\,dx]] Questa è '+K('parti','l’integrazione per parti')+r'. Scegliamo un fattore da derivare, {{u}}, e uno da integrare, {{v\prime}}. La costante {{+C}} si scrive nel risultato finale.'),S('La scelta deve aiutarti',r'La formula è utile se il nuovo integrale {{\int u\prime v\,dx}} è più semplice di quello iniziale.<br><br>Con un polinomio moltiplicato per un’esponenziale o una funzione goniometrica, <strong>derivare il polinomio</strong> ne riduce il grado. Con un logaritmo, derivarlo lo trasforma in una frazione. Sono criteri di scelta, non regole senza eccezioni.')),
 C('Il primo esempio',S('Scegli i due ruoli',r'[[\int xe^x\,dx]] Scegliamo {{u=x}}, perché la derivata è {{u\prime=1}}; scegliamo {{v\prime=e^x}}, perché una primitiva è {{v=e^x}}.<br><br>Non è uno schema composto immediato: la derivata dell’argomento {{x}} dell’esponenziale è {{1}}, non il fattore {{x}}.'),S('Applica la formula',r'[[\int xe^x\,dx=xe^x-\int e^x\,dx]] Il nuovo integrale è immediato, quindi [[\int xe^x\,dx=(x-1)e^x+C]] Controllo: la derivata di {{(x-1)e^x}} è {{e^x+(x-1)e^x=xe^x}}.'))
 ],[
 Q('In ∫ x e^x dx, quale scelta rende più semplice il nuovo integrale?',['u=x, v′=e^x','u=e^x, v′=x','u=x e^x, v′=x','u=1, v′=1'],0,'Derivando x ottieni 1; integrare e^x non ne cambia la forma.'),
 Q('Quale formula è quella dell’integrazione per parti?',['∫uv′ dx = uv + ∫u′v dx','∫uv′ dx = uv − ∫u′v dx','∫uv′ dx = u′v′','∫uv′ dx = (∫u dx)(∫v′ dx)'],1,'Il segno meno deriva dal riordino della regola di derivazione del prodotto.'),
 Q('Qual è ∫ x e^x dx?',['x e^x + C','(x+1)e^x + C','(x−1)e^x + C','x²e^x/2 + C'],2,'La formula dà x e^x − ∫e^x dx.')]),
 Sec('logaritmi','Quando il logaritmo va derivato',[
 C('Il prodotto può essere nascosto',S('Integrare ln x',r'Per {{x>0}}, scriviamo [[\int\ln x\,dx=\int1\cdot\ln x\,dx]] Scegliamo {{u=\ln x}}, {{u\prime=1/x}}, {{v\prime=1}}, {{v=x}}. Il prodotto {{u\prime v}} diventa {{1}}.'),S('Completa il calcolo',r'[[\int\ln x\,dx=x\ln x-\int1\,dx=x\ln x-x+C]] Derivando {{x\ln x-x}} ottieni {{\ln x+1-1=\ln x}}.')),
 C('Un polinomio per un logaritmo',S('La scelta dei fattori',r'[[\int x\ln x\,dx]] Per {{x>0}} scegliamo {{u=\ln x}}, {{u\prime=1/x}}, {{v\prime=x}}, {{v=x^2/2}}.'),S('Il nuovo integrale è un polinomio',r'[[\int x\ln x\,dx=\frac{x^2}{2}\ln x-\int\frac{x}{2}\,dx]] e quindi [[\frac{x^2}{2}\ln x-\frac{x^2}{4}+C]] Qui scegliamo di derivare il logaritmo, anche se è presente un polinomio: è il nuovo integrale a guidare la scelta.'))
 ],[
 Q('Per ∫ ln x dx, quale fattore possiamo considerare nascosto?',['x','1','e^x','1/x'],1,'ln x = 1·ln x: integri 1 e derivi il logaritmo.'),
 Q('Qual è ∫ ln x dx, per x>0?',['x ln x + C','1/x + C','x ln x − x + C','ln x/x + C'],2,'Derivando x ln x compare anche +1, compensato dalla derivata di −x.'),
 Q('Per ∫ x ln x dx, quale scelta semplifica l’integrale residuo?',['Derivare ln x e integrare x.','Integrare entrambi e moltiplicare.','Derivare x e integrare ln x senza altri passaggi.','Sostituire ln x con una costante.'],0,'La derivata 1/x si semplifica con parte della primitiva x²/2.')]),
 Sec('ripetere','Se una volta non basta',[
 C('Ripetere per abbassare il grado',S('Un polinomio di secondo grado',r'[[\int x^2e^x\,dx=x^2e^x-2\int xe^x\,dx]] Abbiamo derivato {{u=x^2}} e integrato {{v\prime=e^x}}. Il grado del polinomio è sceso da {{2}} a {{1}}.'),S('Riusa il risultato già trovato',r'Poiché {{\int xe^x\,dx=(x-1)e^x+C}}, otteniamo [[\int x^2e^x\,dx=(x^2-2x+2)e^x+C]] Nel risultato finale basta una sola costante arbitraria.'),S('Anche una funzione goniometrica',r'[[\int x\cos x\,dx=x\sin x-\int\sin x\,dx]] Ricordando {{\int\sin x\,dx=-\cos x+C}}, il risultato è [[x\sin x+\cos x+C]] Il doppio segno meno diventa un più.')),
 C('Scegliere il metodo',S('Il prodotto da solo non basta',r'In {{\int2x e^{x^2}\,dx}} la funzione interna {{x^2}} ha già la derivata {{2x}} come fattore: conviene il riconoscimento composto.<br><br>In {{\int xe^x\,dx}} quel riconoscimento manca: per parti semplifica il prodotto.<br><br><strong>Prima osserva la struttura, poi scegli il metodo.</strong>'))
 ],[
 Q('Applicando per parti a ∫ x²e^x dx con u=x², quale integrale resta?',['∫ x²e^x dx identico, senza altri termini','2∫ x e^x dx','∫ e^(x²) dx','∫ 2e^x dx'],1,'La derivata di x² è 2x; v resta e^x.'),
 Q('Qual è una primitiva di x cos x?',['x sin x − cos x','x sin x + cos x','x cos x + sin x','sin x'],1,'Per parti dà x sin x − ∫sin x dx, cioè x sin x + cos x.'),
 Q('Per ∫ 2x e^(x²) dx, quale metodo riconosci subito?',['La derivata interna: g=x² e g′=2x.','I fratti semplici.','La divisione tra polinomi.','La regola delle potenze applicata solo a 2x.'],0,'La struttura composta è già completa: una primitiva è e^(x²).')]),
 Recap(['<strong>Per parti viene dalla derivata del prodotto.</strong>','<strong>Scegli un fattore da derivare e uno da integrare</strong>, mirando a un integrale più semplice.','<strong>Polinomio con esponenziale o seno/coseno:</strong> spesso conviene derivare il polinomio.','<strong>Logaritmo:</strong> spesso conviene derivarlo.','<strong>Puoi ripetere il procedimento</strong>; controlla i segni e verifica con la derivata.'])])

L('integrali-definiti','Integrali definiti: significato e calcolo',[
 Sec('accumulare','Dalle piccole variazioni al totale',[
 C('Somma di contributi',S('Un tasso che cambia',r'Se una quantità cambia a un tasso costante {{r}}, in un intervallo di durata {{\Delta t}} la sua variazione è {{r\Delta t}}. Se il tasso cambia, possiamo dividere l’intervallo in piccoli pezzi e sommare contributi del tipo {{f(x_i)\Delta x_i}}.<br><br>L’'+K('definito','integrale definito')+' esprime l’accumulazione complessiva ottenuta rendendo queste suddivisioni sempre più fini.'),S('La scrittura',r'[[\int_a^b f(x)\,dx]] {{a}} e {{b}} sono gli <strong>estremi di integrazione</strong>. A differenza dell’integrale indefinito, il risultato è <strong>un numero</strong>.<br><br>Per un tasso costante {{k}}, [[\int_a^b k\,dx=k(b-a)]] Per esempio, un’entrata continua di 8 euro al minuto per 5 minuti accumula 40 euro.')),
 C('L’idea geometrica',S('Area e segno',r'Per {{a<b}}, se {{f\ge0}}, l’integrale è l’area compresa tra grafico, asse {{x}} e rette {{x=a}}, {{x=b}}. Se {{f}} assume valori negativi, quei contributi entrano con <strong>segno meno</strong>.<br><br>In generale, l’integrale è un’<strong>area con segno</strong>: l’area geometrica totale si calcola con {{\int_a^b|f(x)|\,dx}}.'),S('Una definizione essenziale di Riemann',r'Per una funzione limitata su {{[a,b]}}, {{a<b}}, le somme inferiori e superiori stimano l’integrale per difetto e per eccesso, usando minimo e massimo sui singoli pezzi quando esistono; in generale, estremo inferiore e superiore.<br><br>La funzione è integrabile secondo '+K('riemann','Riemann')+' se possiamo rendere la differenza fra le due somme piccola quanto vogliamo. <strong>Le funzioni continue su un intervallo chiuso e limitato sono integrabili.</strong>'))
 ],[
 Q('Che tipo di risultato dà un integrale definito con estremi fissati?',['Una famiglia di funzioni con +C.','Un numero.','Sempre una funzione lineare.','Sempre zero.'],1,'L’accumulazione si riferisce a un intervallo fissato.'),
 Q('Per a<b, se f è negativa su tutto [a,b], che segno ha l’integrale?',['Negativo.','Sempre positivo perché è un’area.','Zero.','Dipende dalla costante C.'],0,'L’integrale considera i contributi sotto l’asse con segno negativo.'),
 Q('Qual è ∫ da 1 a 4 di 5 dx?',['5','20','15','3'],2,'Il tasso è 5 e la lunghezza dell’intervallo è 4−1=3.')]),
 Sec('fondamentale','Calcolare usando una primitiva',[
 C('Il ponte tra derivata e integrale',S('Il teorema fondamentale',r'Se {{f}} è continua su {{[a,b]}}, la funzione integrale [[A(x)=\int_a^x f(t)\,dt]] è derivabile nei punti interni e {{A\prime(x)=f(x)}}. Il tasso con cui cambia l’accumulazione è la funzione integranda.'),S('La formula operativa',r'Se {{F}} è una qualsiasi primitiva di {{f}}, continua su {{[a,b]}}, [[\int_a^b f(x)\,dx=F(b)-F(a)]] <strong>Valore al limite superiore meno valore al limite inferiore.</strong><br><br>La costante si cancella: {{[F(b)+C]-[F(a)+C]=F(b)-F(a)}}. Nel risultato dell’integrale definito non si aggiunge {{+C}}.')),
 C('Tre passaggi',S('Trova una primitiva',r'[[\int_1^3 2x\,dx]] Una primitiva è {{F(x)=x^2}}.'),S('Valuta e sottrai',r'[[\int_1^3 2x\,dx=[x^2]_1^3=3^2-1^2=8]] Le parentesi {{[F(x)]_a^b}} sono un’abbreviazione per {{F(b)-F(a)}}. Non basta sostituire solo l’estremo superiore.'),S('Se il segno cambia',r'Per {{f(x)=x}} fra {{-1}} e {{1}}, [[\int_{-1}^1x\,dx=0]] I contributi negativi e positivi si compensano. L’area geometrica invece è [[\int_{-1}^1|x|\,dx=1]] e si ottiene sommando le due aree positive.'))
 ],[
 Q('Qual è la formula di calcolo di ∫ da a a b di f(x) dx usando una primitiva F?',['F(a)−F(b)','F(b)−F(a)','F(b)+F(a)+C','F′(b)−F′(a)'],1,'Calcoli la differenza dei valori della primitiva, non della funzione integranda.'),
 Q('Qual è ∫ da 1 a 3 di 2x dx?',['6','9','8','8+C'],2,'Una primitiva è x²: 9−1=8, senza +C.'),
 Q('∫ da −1 a 1 di x dx è zero. Che cosa significa?',['La funzione è zero ovunque.','L’area geometrica totale è zero.','I contributi con segno si compensano.','La funzione non è integrabile.'],2,'L’integrale con segno può essere zero anche quando l’area geometrica è positiva.')]),
 Sec('proprieta','Proprietà che semplificano gli esercizi',[
 C('Somma, intervalli e orientamento',S('Le proprietà operative',r'Valgono la linearità e l’additività sugli intervalli: [[\int_a^b(f+g)\,dx=\int_a^b f\,dx+\int_a^b g\,dx]] [[\int_a^b f\,dx=\int_a^c f\,dx+\int_c^b f\,dx]] Per convenzione, [[\int_b^a f\,dx=-\int_a^b f\,dx\qquad\int_a^a f\,dx=0]] Le formule richiedono l’integrabilità sui tratti considerati.'),S('Simmetria e valore medio',r'Su {{[-a,a]}}, con {{a>0}}, una funzione integrabile <strong>dispari</strong> ha integrale zero; per una funzione <strong>pari</strong> l’integrale è il doppio di quello su {{[0,a]}}.<br><br>Il valore medio di {{f}} su {{[a,b]}}, {{a<b}}, è [[f_{\mathrm{medio}}=\frac{1}{b-a}\int_a^b f(x)\,dx]] Se {{f}} è continua, assume quel valore in almeno un punto dell’intervallo.')),
 C('Una sostituzione con gli estremi',S('Cambiano anche i limiti',r'[[\int_0^1 2x e^{x^2}\,dx]] Poniamo {{u=x^2}}, {{du=2x\,dx}}. Gli estremi diventano {{u(0)=0}} e {{u(1)=1}}: [[\int_0^1e^u\,du=e-1]] Con limiti già trasformati, non serve tornare a {{x}}.'),S('Un altro esempio',r'[[\int_0^2\frac{dx}{x+1}]] Con {{u=x+1}}, i nuovi estremi sono {{1}} e {{3}}. Quindi [[\int_1^3\frac{du}{u}=\ln3]] Puoi anche trovare {{\ln|x+1|}} e valutarla direttamente agli estremi originali. <strong>Non mescolare limiti in {{x}} e integranda in {{u}}.</strong>'))
 ],[
 Q('Se ∫ da 0 a 2 di f(x) dx vale 7, quanto vale l’integrale da 2 a 0?',['7','0','−7','14'],2,'Invertire l’ordine degli estremi cambia il segno.'),
 Q('In ∫ da 0 a 2 di 1/(x+1) dx, con u=x+1, quali sono i nuovi estremi?',['0 e 2','1 e 3','−1 e 1','0 e 3'],1,'Sostituisci gli estremi nella relazione u=x+1.'),
 Q('Su [0,4] l’integrale di f vale 12. Qual è il suo valore medio?',['12','48','4','3'],3,'Dividi l’integrale per la lunghezza dell’intervallo: 12/4=3.')]),
 Sec('economia','Un’applicazione ai costi',[
 C('Da costo marginale a costo totale',S('Il modello',r'Supponiamo che il costo totale sia una funzione derivabile {{K(q)}} della quantità prodotta, trattata come variabile continua. Il costo marginale è {{K\prime(q)}}.<br><br>Se [[K\prime(q)=4q+6\qquad K(0)=100]] l’integrale indefinito ricostruisce la famiglia [[K(q)=2q^2+6q+C]] Il costo iniziale impone {{C=100}}.'),S('La variazione e il totale',r'Produrre da {{q=0}} a {{q=5}} comporta una variazione di costo [[\int_0^5(4q+6)\,dq=80]] Quindi {{K(5)=100+80=180}}. <strong>L’integrale del costo marginale dà la variazione di costo, non da solo il costo totale.</strong> Qui le unità monetarie sono euro e {{q}} conta unità di prodotto.'),S('Controlla prima le condizioni',r'La formula {{F(b)-F(a)}} non autorizza ad attraversare senza controllo un punto in cui la funzione non è definita. Per esempio {{1/x}} ha un problema in {{0}}: l’integrale da {{-1}} a {{1}} non si calcola semplicemente sottraendo due logaritmi.<br><br>Questi sono <strong>integrali impropri</strong>, un argomento separato dal percorso attuale.'))
 ],[
 Q('Se K′ è il costo marginale, che cosa dà ∫ da 0 a 5 di K′(q) dq?',['Sempre il costo totale K(5).','La variazione K(5)−K(0).','Il costo fisso K(0).','La derivata seconda K″(5).'],1,'Per ottenere il costo totale devi aggiungere il costo iniziale.'),
 Q('Con K′(q)=4q+6 e K(0)=100, quanto vale K(5)?',['80','100','180','200'],2,'La variazione è 80; aggiungi il costo iniziale 100.'),
 Q('Puoi calcolare ∫ da −1 a 1 di 1/x dx semplicemente con ln|1|−ln|−1|?',['Sì, vale zero.','Sì, perché il modulo elimina ogni problema.','No: c’è una singolarità in 0 e occorre trattare gli integrali impropri.','Sì, aggiungendo C.'],2,'Devi controllare che l’integranda sia definita e integrabile sul tratto considerato.')]),
 Recap(['<strong>Definito:</strong> un’accumulazione con segno su un intervallo, quindi un numero.',r'<strong>Con una primitiva:</strong> {{F(b)-F(a)}}, senza {{+C}}.','<strong>Area geometrica:</strong> considera il valore assoluto se la funzione cambia segno.','<strong>Sostituzione:</strong> cambia anche gli estremi, oppure torna alla variabile originale prima di valutarli.','<strong>In economia:</strong> integrando un tasso marginale trovi la variazione; il dato iniziale completa il totale.'])])

